import { google } from "googleapis";

export async function GET() {
  try {
    // ✅ Validate env first (prevents silent crashes)
    if (!process.env.GOOGLE_CLIENT_EMAIL || !process.env.GOOGLE_PRIVATE_KEY) {
      throw new Error("Missing Google credentials in .env");
    }

    const auth = new google.auth.JWT({
      email: process.env.GOOGLE_CLIENT_EMAIL,
      key: process.env.GOOGLE_PRIVATE_KEY.replace(/\\n/g, "\n"),
      scopes: ["https://www.googleapis.com/auth/webmasters.readonly"],
    });

    // ✅ Explicitly authorize (IMPORTANT)
    await auth.authorize();

    const searchconsole = google.searchconsole({
      version: "v1",
      auth,
    });

    const response = await searchconsole.searchanalytics.query({
      siteUrl: process.env.GOOGLE_SITE_URL, // ✅ move to .env
      requestBody: {
        startDate: "2024-01-01",
        endDate: "2024-01-31",
        dimensions: ["query"],
      },
    });

    return Response.json(response.data);
  } catch (error) {
    console.error("GSC ERROR:", error); // ✅ better debugging

    return Response.json(
      {
        error: error.message,
        details: error.errors || null,
      },
      { status: 500 }
    );
  }
}